set -euo pipefail
upload_dir=$(getent passwd "$SUDO_USER" | cut -d: -f6)
cd /opt/news-flow/current
runuser -u news-flow -- /opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {gunzipSync} from 'node:zlib';import {createRequire} from 'node:module';import {DatabaseSync} from 'node:sqlite';const require=createRequire('/opt/news-flow/current/package.json'),ch=require('cheerio'),root='/var/lib/news-flow/qc-recover25-20261122',db=new DatabaseSync('/var/lib/news-flow/news-flow-runtime/write.sqlite',{readOnly:true}),rows=db.prepare("SELECT url,error FROM article_links WHERE site='edition.cnn.com' AND parse_status='fail'").all(),old=JSON.parse(fs.readFileSync('/var/lib/news-flow/qc-alt25-20261122/followup.json')),r={at:new Date().toISOString(),rows:[]},clean=s=>String(s||'').normalize('NFC').replace(/[“”]/g,'"').replace(/[‘’]/g,"'").replace(/\s+/g,' ').trim();db.close();for(const row of rows){const p=old.checks.find(p=>p.kind==='cnn'&&new URL(p.url).pathname===new URL(row.url).pathname);if(!p){r.rows.push({...row,archived:false});continue;}const $=ch.load(gunzipSync(fs.readFileSync(p.file)).toString()),a=JSON.parse($('script[type="application/ld+json"]').first().text())[0],body=$('article.article--lite').clone();body.find('.source--lite').remove();body.find('p').filter((i,e)=>clean($(e).text())==='See Full Web Article').remove();const paras=body.find('p.paragraph--lite').toArray().map(e=>clean($(e).text())).filter(Boolean),schema=clean(a.articleBody);let matched=0,cursor=0;const missing=[];for(const text of paras){const pos=schema.indexOf(text,cursor);if(pos<0)missing.push(text.slice(0,120));else{matched+=text.length;cursor=pos+text.length;}}r.rows.push({...row,archived:true,titleMatches:clean(a.headline)===clean($('h2.headline').text()),description:a.description,descriptionInBody:schema.includes(clean(a.description)),coverage:matched/schema.length,missingParagraphs:missing,restrictedSelector:$('.article__content').length});}fs.writeFileSync(root+'/cnn-residual-inspection.json',JSON.stringify(r,null,2));console.log(JSON.stringify(r));
NODE
install -o "$SUDO_USER" -m 0600 /var/lib/news-flow/qc-recover25-20261122/cnn-residual-inspection.json "$upload_dir/.qc-recover25-cnn-residual-inspection.json"
